// Typed client for the red-team API. Types come from schema.d.ts, generated by:
//   python scripts/export_openapi.py && npx openapi-typescript openapi.json -o src/api/schema.d.ts
import { api, post } from '../api';
import type { components } from './schema';

export type S = components['schemas'];
export type Catalog = S['Catalog'];
export type ExperimentConfig = S['ExperimentConfig'];
export type ValidationResult = S['ValidationResult'];
export type RunProgress = S['RunProgress'];
export type EpisodePage = S['EpisodePage'];
export type EpisodeSummary = S['EpisodeSummary'];
export type EpisodeDetail = S['EpisodeDetail'];
export type Trace = S['Trace'];
export type Report = S['Report'];
export type Matrix = S['Matrix'];

export interface EpisodeQuery {
  task?: string; strategy?: string; defense?: string; verdict?: S['EpisodeSummary']['verdict'];
  q?: string; include_baseline?: boolean; cursor?: string; limit?: number;
}

const enc = encodeURIComponent;
const query = (params: object) => {
  const entries = Object.entries(params).filter(([, v]) => v !== undefined && v !== '');
  return entries.length ? '?' + new URLSearchParams(entries.map(([k, v]) => [k, String(v)])).toString() : '';
};

export const redteam = {
  catalog: () => api<Catalog>('/catalog'),
  validate: (config: ExperimentConfig) => post<ValidationResult>('/experiments/validate', config),
  testTarget: (target: S['TargetRef']) => post<S['TargetTestResult']>('/targets/test', target),
  launch: (config: ExperimentConfig) => post<{ id: string }>('/runs', config),
  pause: (runId: string) => post<RunProgress>(`/runs/${enc(runId)}/pause`),
  resume: (runId: string) => post<RunProgress>(`/runs/${enc(runId)}/resume`),
  progress: (runId: string) => api<RunProgress>(`/runs/${enc(runId)}/progress`),
  episodes: (runId: string, q: EpisodeQuery = {}) => api<EpisodePage>(`/runs/${enc(runId)}/episodes${query(q)}`),
  episode: (runId: string, episodeId: string) => api<EpisodeDetail>(`/runs/${enc(runId)}/episodes/${enc(episodeId)}`),
  trace: (runId: string, episodeId: string) => api<Trace>(`/runs/${enc(runId)}/episodes/${enc(episodeId)}/trace`),
  report: (runId: string) => api<Report>(`/runs/${enc(runId)}/report`),
  matrix: (runId: string, defense = 'none') => api<Matrix>(`/runs/${enc(runId)}/matrix${query({ defense })}`),
};
